    out += section(154, 'faq-columns', '<div class="row"><div class="col-12">' + heading('','Still have questions?','') + '</div><div class="col-lg-6">' + faq([['How can I buy a plant?','Choose a plant online or visit our garden center.'],['Do I need to pay in advance?','Consultations can be scheduled before any project deposit.'],['Which payment options are available?','We accept major cards and secure bank transfer.'],['Can I track delivery?','Yes, local delivery updates are sent by email.']]) + '</div><div class="col-lg-6">' + faq([['How can I contact the team?','Use the consultation form or call during studio hours.'],['Can I request a refund?','Damaged plants are covered by our arrival guarantee.'],['How should I care for the plant?','Every plant includes a concise care guide.'],['Are your plants responsibly sourced?','We prioritize regional growers and responsible nurseries.']]) + '</div></div>');
